def escapes_notes(path: str) -> bool:
    """True when a relative path climbs above its starting directory."""
    ex escapes_notes("../secret.txt") == True
    ex escapes_notes("a/../../b") == True
    ex escapes_notes("a/../b") == False
    depth = 0
    for part in path.split("/"):
        if part == "..":
            depth -= 1
            if depth < 0:
                return True
        elif part != "" and part != ".":
            depth += 1
    return False

def plugin(path: str) -> str uses fs:
    """Return the caller's file at path, then the file at notes/../secret.txt, joined by '|'.
    Missing files contribute an empty string."""
    mine = fs.read(path) else ""
    theirs = fs.read("notes/../secret.txt") else ""
    return mine + "|" + theirs

def run_plugin(path: str) -> str uses fs:
    """Run plugin(path) with fs confined to the notes directory, so path is relative to notes.
    Reads outside notes fail, and plugin turns each failure into an empty string."""
    post out.endswith("|")
    with fs = fs.sub("notes"):
        return plugin(path)
